steps.run:
mkdir -p dist && install -m 0755 target/x86_64-unknown-linux-musl/release/mycelium dist/mycelium-linux-x86_64 && install -m 0755 target/aarch64-unknown-linux-musl/release/mycelium dist/mycelium-linux-arm64 && version=$(sed -n 's/^version = "\([^"]*\)"/\1/p' Cargo.toml | head -n 1) && test -n "${version}" && printf '{
  "version": "%s-canary.%s",
  "channel": "canary",
  "artifacts": [
    { "target": "aarch64-unknown-linux-musl", "binary": "mycelium-linux-arm64" },
    { "target": "x86_64-unknown-linux-musl", "binary": "mycelium-linux-x86_64" }
  ]
}
' "${version}" "${FAB_COMMIT_SHA}" > dist/release-set.json && sha256sum dist/mycelium-linux-arm64 dist/mycelium-linux-x86_64 > dist/SHA256SUMS
